{"version":3,"sources":["powpow/rainbow-border.scss","powpow/rainbow-border.css"],"names":[],"mappings":"AAIA;EACI,kBAAA;EACA,mBAAA;EACA,gBAAA;ACHJ;ADKI;EACI,WAAA;EACA,kBAAA;EACA,UAAA;EACA,YAAA;EACA,aAAA;EACA,WAAA;EACA,gBAAA;EACA,iSAAA;EAQA,0CAAA;EACA,UAAA;EACA,oBAAA;ACVR;ADaI;EACI,WAAA;EACA,kBAAA;EACA,QAAA;EACA,UAAA;EACA,WAAA;EACA,SAAA;EACA,gBAAA;EACA,gBAAA;EACA,UAAA;EACA,oBAAA;ACXR;ADcI;EACI,kBAAA;EACA,UAAA;ACZR;AD7BA;EA4CI,iDAAA;ACZJ;;ADeA;EACI;IAAK,wBAAA;ECXP;AACF;ADaA;EACI;IAAW,mBAAA;ECVb;EDWE;IAAM,sBAAA;ECRR;AACF","file":"rainbow-border.css","sourcesContent":["// ============================================================\n// Cornice arcobaleno animata per il portfolio-card di Rumble Smash\n// ============================================================\n\n.rainbow-card {\n    position: relative;\n    border-radius: 12px;\n    overflow: hidden;\n\n    &::before {\n        content: '';\n        position: absolute;\n        top: -100%;\n        right: -100%;\n        bottom: -100%;\n        left: -100%;\n        border-radius: 0;\n        background: conic-gradient(\n            from 0deg,\n            #ff0000, #ff3300, #ff6600, #ff9900, #ffcc00, #ffff00,\n            #ccff00, #99ff00, #66ff00, #33ff00, #00ff00, #00ff33,\n            #00ff66, #00ff99, #00ffcc, #00ffff, #00ccff, #0099ff,\n            #0066ff, #0033ff, #0000ff, #6600ff, #cc00ff, #ff00ff,\n            #ff0099, #ff0066, #ff0033, #ff0000\n        );\n        animation: rainbow-spin 4s linear infinite;\n        z-index: 0;\n        pointer-events: none;\n    }\n\n    &::after {\n        content: '';\n        position: absolute;\n        top: 8px;\n        right: 8px;\n        bottom: 8px;\n        left: 8px;\n        border-radius: 0;\n        background: #fff;\n        z-index: 1;\n        pointer-events: none;\n    }\n\n    > * {\n        position: relative;\n        z-index: 2;\n    }\n\n    animation: rainbow-bounce 2s ease-in-out infinite;\n}\n\n@keyframes rainbow-spin {\n    to { transform: rotate(1turn); }\n}\n\n@keyframes rainbow-bounce {\n    0%, 100% { transform: scale(1); }\n    50% { transform: scale(1.03); }\n}",".rainbow-card {\n  position: relative;\n  border-radius: 12px;\n  overflow: hidden;\n}\n.rainbow-card::before {\n  content: \"\";\n  position: absolute;\n  top: -100%;\n  right: -100%;\n  bottom: -100%;\n  left: -100%;\n  border-radius: 0;\n  background: conic-gradient(from 0deg, #ff0000, #ff3300, #ff6600, #ff9900, #ffcc00, #ffff00, #ccff00, #99ff00, #66ff00, #33ff00, #00ff00, #00ff33, #00ff66, #00ff99, #00ffcc, #00ffff, #00ccff, #0099ff, #0066ff, #0033ff, #0000ff, #6600ff, #cc00ff, #ff00ff, #ff0099, #ff0066, #ff0033, #ff0000);\n  animation: rainbow-spin 4s linear infinite;\n  z-index: 0;\n  pointer-events: none;\n}\n.rainbow-card::after {\n  content: \"\";\n  position: absolute;\n  top: 8px;\n  right: 8px;\n  bottom: 8px;\n  left: 8px;\n  border-radius: 0;\n  background: #fff;\n  z-index: 1;\n  pointer-events: none;\n}\n.rainbow-card > * {\n  position: relative;\n  z-index: 2;\n}\n.rainbow-card {\n  animation: rainbow-bounce 2s ease-in-out infinite;\n}\n\n@keyframes rainbow-spin {\n  to {\n    transform: rotate(1turn);\n  }\n}\n@keyframes rainbow-bounce {\n  0%, 100% {\n    transform: scale(1);\n  }\n  50% {\n    transform: scale(1.03);\n  }\n}"]}